begin;
create table mmb_backup_v1023_video_reference_workflows_20260711 as
select * from workflows where app_id = '575c4fa3-4268-4ff5-8100-248e4a3739c7';
update workflows
set graph = convert_from(decode($graph$$graph$, 'base64'), 'UTF8'),
    updated_at = now()
where id = '84248889-cf8f-459e-a364-5dd5200ee4d0'
  and version = 'draft';
commit;
select id, version, jsonb_array_length(graph::jsonb->'nodes') as node_count,
       graph::jsonb #> '{nodes,0,data,variables}' as start_variables
from workflows where id = '84248889-cf8f-459e-a364-5dd5200ee4d0';